func basicAuthHeaderForCredential(token string) string {
	payload := strings.TrimSpace("Basic {username}:{password}")
	if scheme, rest, ok := strings.Cut(payload, " "); ok && strings.EqualFold(strings.TrimSpace(scheme), "Basic") {
		payload = strings.TrimSpace(rest)
	}
	replacements := map[string]string{
		"username":              token,
		"RANKMATH_USERNAME":     token,
		"user":                  token,
		"app_password":          token + "-secondary",
		"RANKMATH_APP_PASSWORD": token + "-secondary",
		"password":              token + "-secondary",
		"secret":                token + "-secondary",
		"token":                 token + "-secondary",
		"access_token":          token + "-secondary",
	}
	for key, value := range replacements {
		payload = strings.ReplaceAll(payload, "{"+key+"}", value)
	}
	return "Basic " + base64.StdEncoding.EncodeToString([]byte(payload))
}

func assertAuthHeaderCredential(t *testing.T, cfg *config.Config, wantToken, rejectToken string) {
	t.Helper()
	got := cfg.AuthHeader()
	want := basicAuthHeaderForCredential(wantToken)
	if got != want {
		t.Fatalf("AuthHeader() = %q, want header derived from %q", got, wantToken)
	}
	if rejectToken != "" && got == basicAuthHeaderForCredential(rejectToken) {
		t.Fatalf("AuthHeader() used rejected credential %q", rejectToken)
	}
}

func TestAuthHeaderRequiresEveryCredential(t *testing.T) {
	t.Run("missing RANKMATH_USERNAME", func(t *testing.T) {
		cfg := configWithCredential("complete-secret")
		cfg.RankmathUsername = ""
		if got := cfg.AuthHeader(); got != "" {
			t.Fatalf("AuthHeader() = %q, want empty", got)
		}
	})
	t.Run("missing RANKMATH_APP_PASSWORD", func(t *testing.T) {
		cfg := configWithCredential("complete-secret")
		cfg.RankmathAppPassword = ""
		if got := cfg.AuthHeader(); got != "" {
			t.Fatalf("AuthHeader() = %q, want empty", got)
		}
	})
}

func captureCredentialStderr(t *testing.T, fn func()) string {
	t.Helper()
	old := os.Stderr
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	os.Stderr = w
	done := make(chan string, 1)
	go func() {
		var buf bytes.Buffer
		_, _ = io.Copy(&buf, r)
		done <- buf.String()
	}()
	drained := false
	defer func() {
		os.Stderr = old
		_ = w.Close()
		if !drained {
			<-done
		}
		_ = r.Close()
	}()
	fn()
	_ = w.Close()
	os.Stderr = old
	captured := <-done
	drained = true
	_ = r.Close()
	return captured
}

func TestCaptureCredentialStderrDrainsConcurrently(t *testing.T) {
	want := strings.Repeat("x", 128*1024)
	got := captureCredentialStderr(t, func() {
		_, _ = os.Stderr.Write([]byte(want))
	})
	if got != want {
		t.Fatalf("captured stderr length = %d, want %d", len(got), len(want))
	}
}
